import SwiftUI
struct SettingsView: View { @Environment(PrivacySettings.self) private var privacy; @Environment(SecurityService.self) private var security; var body: some View { @Bindable var privacy = privacy; @Bindable var security = security; Form { Section("Privacy") { Toggle("Privacy mode shows initials", isOn: $privacy.privacyModeEnabled); Toggle("Allow ICD codes in helper output", isOn: $privacy.allowICDCodes); Stepper("Lock after \(security.inactivityMinutes) minutes", value: $security.inactivityMinutes, in: 1...30) } Section("Important notice") { Text("These safeguards do not by themselves establish HIPAA compliance. Organizational approval and appropriate device management may still be required.") } Section("Local data") { Button("Delete all local data", role: .destructive) { } } }.navigationTitle("Settings") } }
